224	    protected Set<Pet> getPetsInternal() {
225	        if (this.pets == null) {
226	            this.pets = new HashSet<>();
227	        }
228	        return this.pets;
229	    }
230	
231	    protected void setPetsInternal(Set<Pet> pets) {
232	        this.pets = pets;
233	    }
234	
235	    public List<Pet> getPets() {
236	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
237	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
238	        return Collections.unmodifiableList(sortedPets);
239	    }
240	
241	    public void setPets(List<Pet> pets) {
242	        this.pets = new HashSet<>(pets);
243	    }
244	
245	    public void addPet(Pet pet) {
246	        getPetsInternal().add(pet);
247	        pet.setOwner(this);
248	    }
249	
250	    /**
251	     * Return the Pet with the given name, or null if none found for this Owner.
252	     *
253	     * @param name to test
254	     * @return true if pet name is already in use
255	     */
256	    public Pet getPet(String name) {
257	        return getPet(name, false);
258	    }
259	
260	    /**
261	     * Return the Pet with the given name, or null if none found for this Owner.
262	     *
263	     * @param name to test
264	     * @return true if pet name is already in use
265	     */
266	    public Pet getPet(String name, boolean ignoreNew) {
267	        name = name.toLowerCase();
268	        for (Pet pet : getPetsInternal()) {
269	            if (!ignoreNew || !pet.isNew()) {
270	                String compName = pet.getName();
271	                compName = compName.toLowerCase();
272	                if (compName.equals(name)) {
273	                    return pet;
274	                }
275	            }
276	        }
277	        return null;
278	    }
279	
280	    public Pet getPet(Integer petId) {
281	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
282	    }
283	
284	    @Override
285	    public String toString() {
286	        return new ToStringCreator(this)
287	
288	            .append("id", this.getId())
289	            .append("new", this.isNew())
290	            .append("lastName", this.getLastName())
291	            .append("firstName", this.getFirstName())
292	            .append("address", this.address)
293	            .append("city", this.city)
294	            .append("telephone", this.telephone)
295	            .append("email", this.email)
296	            .toString();
297	    }
298	}
