25	/**
26	 * Maps Owner & OwnerDto using Mapstruct
27	 */
28	@Mapper(uses = PetMapper.class)
29	public interface OwnerMapper {
30	
31	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
32	    @Mapping(target = "initials", expression = "java(initials(owner))")
33	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
34	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
35	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
36	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
37	    @Mapping(target = "locality", expression = "java(locality(owner))")
38	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
39	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
40	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
41	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
42	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
43	    OwnerDto toOwnerDto(Owner owner);
44	
45	    /** The owner's stored E.164 telephone formatted for humans - see {@link OwnerTelephones#toDisplay}. */
46	    default String telephoneDisplay(Owner owner) {
47	        if (owner == null) {
48	            return null;
49	        }
50	        return OwnerTelephones.toDisplay(owner.getTelephone());
51	    }
52	
53	    /** The owner's age band derived from birthDate against registrationDate - see {@link AgeBand};
54	     * null when either date is absent. */
55	    default String ageBand(Owner owner) {
56	        if (owner == null) {
57	            return null;
58	        }
59	        AgeBand ageBand = AgeBand.forOwner(owner);
60	        return ageBand == null ? null : ageBand.name();
61	    }
62	
63	    /** The owner's derived duplicate-detection key - see {@link OwnerIdentities}. */
64	    default String identityKey(Owner owner) {
65	        if (owner == null) {
66	            return null;
67	        }
68	        return OwnerIdentities.of(owner);
69	    }
70	
71	    /** The owner's preferred contact channel - 'EMAIL' when an email is present, otherwise 'PHONE'. */
72	    default String contactPreference(Owner owner) {
73	        if (owner == null) {
74	            return null;
75	        }
76	        return ContactPreference.forOwner(owner).name();
77	    }
78	
79	    /** The canonical region derived from the owner's postcode - the same REGION that forms the
80	     * customer code (see {@link OwnerIdentities} and the {@code <REGION>-<HASH8>} customer code),
81	     * or 'UNKNOWN' when the postcode resolves to no known region. */
82	    default String locality(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        return Locality.forPostcode(owner.getPostcode());
87	    }
88	
89	    /** The IANA timezone name for the owner's region (see {@link Timezone} and {@link #locality}),
90	     * or null when the region has no known timezone. */
91	    default String timezone(Owner owner) {
92	        if (owner == null) {
93	            return null;
94	        }
95	        return Timezone.forRegion(locality(owner));
96	    }
97	
98	    /** Format the stored names as 'LastName, FirstName'. */
99	    default String displayName(Owner owner) {
100	        if (owner == null) {
101	            return null;
102	        }
103	        return owner.getLastName() + ", " + owner.getFirstName();
104	    }
105	
106	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
107	    default String initials(Owner owner) {
108	        if (owner == null) {
109	            return null;
110	        }
111	        return initial(owner.getFirstName()) + initial(owner.getLastName());
112	    }
113	
114	    private static String initial(String name) {
115	        if (name == null || name.isEmpty()) {
116	            return "";
117	        }
118	        return Character.toUpperCase(name.charAt(0)) + ".";
119	    }
120	
121	    /**
122	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
123	     * last two digits of the registrationDate year (e.g. 'NSW-1A2B3C4D-M26'). Derived from the owner's
124	     * own fields; null until both the customer code and registration date are assigned.
125	     */
126	    default String membershipNumber(Owner owner) {
127	        return MembershipNumber.of(owner);
128	    }
129	
130	    /** The Luhn check digit over the digits of the owner's customerCode; null until a code is assigned. */
131	    default Integer checkDigit(Owner owner) {
132	        if (owner == null || owner.getCustomerCode() == null) {
133	            return null;
134	        }
135	        return Luhn.checkDigit(owner.getCustomerCode());
136	    }
137	
138	    /**
139	     * The owner's membership points, scored from the owner's own fields; null when there
140	     * is no owner.
141	     *
142	     * @see MembershipPoints
143	     */
144	    default Integer membershipPoints(Owner owner) {
145	        if (owner == null) {
146	            return null;
147	        }
148	        return MembershipPoints.of(owner);
149	    }
150	
151	    /**
152	     * The owner's numeric membership level, mapped from the owner's membership points; null
153	     * when there is no owner.
154	     *
155	     * @see MembershipLevel
156	     */
157	    default Integer membershipLevel(Owner owner) {
158	        if (owner == null) {
159	            return null;
160	        }
161	        return MembershipLevel.of(owner);
162	    }
163	
164	    Owner toOwner(OwnerDto ownerDto);
165	
166	    @Mapping(target = "id", ignore = true)
167	    @Mapping(target = "pets", ignore = true)
168	    Owner toOwner(OwnerFieldsDto ownerDto);
169	
170	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
171	
172	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
173	
174	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
175	        OwnerPageDto ownerPageDto = new OwnerPageDto();
176	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
177	        ownerPageDto.setPage(ownerPage.getNumber());
178	        ownerPageDto.setSize(ownerPage.getSize());
179	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
180	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
181	        return ownerPageDto;
182	    }
183	}
